```t
t 1
gate loops
task digit_distance_nums(a: int, b: int) returns (r: int)
  requires a >= 0
  requires b >= 0
  ensures r == dd(a, b)
spec fun dd(a: int, b: int): int
  decreases a + b
= if a == 0 and b == 0 then 0
  else if a == 0 then dd(0, b - 10 * (b / 10)) + (b % 10)
  else if b == 0 then dd(a - 10 * (a / 10), 0) + (a % 10)
  else dd(a - 10 * (a / 10), b - 10 * (b / 10)) + (if a % 10 >= b % 10 then a % 10 - b % 10 else b % 10 - a % 10)
{
  r := 0;
  var x: int := a;
  var y: int := b;
  while x != 0 or y != 0
    invariant x >= 0
    invariant y >= 0
    invariant r == dd(a - x, b - y)
    decreases x + y
  {
    var dx: int := 0;
    var dy: int := 0;
    var tx: int := x;
    var ty: int := y;
    var cx: int := 0;
    while cx < 10
      invariant 0 <= cx <= 10
      invariant tx == x - 10 * cx + dx
      decreases 10 - cx
    {
      if tx >= 10 {
        tx := tx - 10;
        cx := cx + 1;
      } else {
        dx := tx;
        tx := 0;
      }
    }
    var cy: int := 0;
    while cy < 10
      invariant 0 <= cy <= 10
      invariant ty == y - 10 * cy + dy
      decreases 10 - cy
    {
      if ty >= 10 {
        ty := ty - 10;
        cy := cy + 1;
      } else {
        dy := ty;
        ty := 0;
      }
    }
    x := x - 10 * cx;
    y := y - 10 * cy;
    if dx >= dy {
      r := r + (dx - dy);
    } else {
      r := r + (dy - dx);
    }
  }
}
```
